module util {
  function money_round(amount: decimal) -> decimal
    using (round(amount, 2));

  function money_round(amount: decimal, places: int64) -> decimal
    using (round(amount, places));

  function total_of(variadic amounts: decimal) -> decimal
    using (round(sum(array_unpack(amounts)), 2));

  function apply_discount(amount: decimal, pct: decimal, floor_amount: optional decimal) -> decimal
    using (
      with d := round(amount * (1n - pct / 100n), 2)
      select max({d} union floor_amount)
    );

  function gross_with_tax(net: decimal, named only tax_pct: decimal = 0) -> decimal
    using (round(net * (1n + tax_pct / 100n), 2));

  function installments(total: decimal, count: int64) -> set of decimal
    using (
      with
        denominator := (if count < 1 then 1 else count),
        each_val := round(total / denominator, 2)
      select
        if count < 1 then
          <decimal>{}
        else
          (
            with indices := range_unpack(range(1, count + 1))
            select if indices < count then each_val else total - (count - 1) * each_val
          )
    );
}

module billing {
  type Customer {
    required name: str {
      constraint exclusive;
    }
    required discount_pct: decimal {
      default := 0n;
    }
  }

  type Invoice {
    required code: str {
      constraint exclusive;
    }
    required link customer -> billing::Customer;
    required property paid -> bool {
      default := false;
    }
    property minimum_charge -> decimal;
    required property installment_count -> int64 {
      default := 1;
    }

    # Computeds
    multi link lines := .<invoice[is billing::LineItem];
    property subtotal := util::money_round(sum(.lines.line_total));
    property total_due := util::apply_discount(.subtotal, .customer.discount_pct, .minimum_charge);
  }

  type LineItem {
    required link invoice -> billing::Invoice;
    required property description -> str;
    required property qty -> int64;
    required property unit_price -> decimal {
      constraint expression on (__subject__ = util::money_round(__subject__));
    }
    property line_total := util::money_round(.qty * .unit_price);
  }

  function customer_outstanding(customer_name: str) -> decimal {
    volatility := 'Stable';
    using (
      util::money_round(sum(
        (
          select billing::Invoice
          filter .customer.name = customer_name and not .paid
        ).total_due
      ))
    );
  }
}
